CREATE INDEX idx_users_email ON users (email);

SELECT id, name
FROM users
WHERE email = 'sam@example.com';

CREATE INDEX idx_orders_customer_id ON orders (customer_id);

SELECT id, total
FROM orders
WHERE customer_id = 42;

CREATE INDEX idx_products_price ON products (price);

SELECT id, name
FROM products
WHERE price >= 100 AND price < 500
ORDER BY price;

SELECT *
FROM users
WHERE is_active = TRUE;

-- Approximate on-disk size of one index
SELECT pg_size_pretty(pg_relation_size('idx_users_email')) AS index_size;

-- Table size including its indexes and other auxiliary storage
SELECT pg_size_pretty(pg_total_relation_size('users')) AS total_size;
